"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[1418],{1934(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/kickoff-meeting","title":"Pilot Kickoff Meeting (AI Lead): Why, What, Who \u2014 Enterprise Doc Q&A Example","description":"This tutorial explains the kickoff meeting that happens right after the AI Lead submits the \u201cAI Lead Response Doc\u201d. The example is your Executive Document Q&A tool (meeting notes/packs \u2192 cited answers). The purpose of...","source":"@site/docs/part1-enterprise-ai-delivery/04-kickoff-meeting.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/04-kickoff-meeting","permalink":"/tutorials/part1-enterprise-ai-delivery/04-kickoff-meeting","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":4,"frontMatter":{"title":"Pilot Kickoff Meeting (AI Lead): Why, What, Who \u2014 Enterprise Doc Q&A Example","slug":"/part1-enterprise-ai-delivery/04-kickoff-meeting","description":"This tutorial explains the kickoff meeting that happens right after the AI Lead submits the \u201cAI Lead Response Doc\u201d. The example is your Executive Document Q&A tool (meeting notes/packs \u2192 cited answers). The purpose of...","sidebar_label":"4. Pilot kickoff meeting","pagination_label":"4. Pilot kickoff meeting","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"3. AI lead response document","permalink":"/tutorials/part1-enterprise-ai-delivery/03-ai-lead-response"},"next":{"title":"5. Seven days after kickoff","permalink":"/tutorials/part1-enterprise-ai-delivery/05-seven-days-after-kickoff"}}');var s=n(4848),o=n(8453),a=n(8172);const r=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/04-kickoff-meeting.html","route":"/part1-enterprise-ai-delivery/04-kickoff-meeting","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"Pilot Kickoff Meeting (AI Lead)","title":"Pilot Kickoff Meeting (AI Lead): Why, What, Who \u2014 Enterprise Doc Q&A Example","description":"This tutorial explains the kickoff meeting that happens right after the AI Lead submits the \u201cAI Lead Response Doc\u201d. The example is your Executive Document Q&A tool (meeting notes/packs \u2192 cited answers). The purpose of...","readingMinutes":5,"bodyClass":"","normalizeMath":false,"toc":[{"id":"why","label":"1) Why this kickoff meeting exists"},{"id":"inputs","label":"2) Inputs you bring (so the meeting is productive)"},{"id":"who","label":"3) Who must attend (and why)"},{"id":"agenda","label":"4) Agenda (60\u201390 minutes)"},{"id":"decisions","label":"5) The 3 decisions you must get (non-negotiable)"},{"id":"questions","label":"6) Questions to ask (by role)"},{"id":"outputs","label":"7) Outputs you produce after the meeting (within 24\u201348 hours)"},{"id":"anti","label":"8) Common failure modes (and how to avoid them)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This tutorial explains the kickoff meeting that happens right after the AI Lead submits the \u201cAI Lead Response Doc\u201d.\\n      The example is your <strong>Executive Document Q&amp;A</strong> tool (meeting notes/packs \u2192 cited answers).\\n      The purpose of this kickoff is to turn the plan into <strong>committed decisions</strong> so delivery can start safely.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#why\\">Why this meeting exists</a></li>\\n      <li><a href=\\"#inputs\\">Inputs to bring</a></li>\\n      <li><a href=\\"#who\\">Who must attend</a></li>\\n      <li><a href=\\"#agenda\\">Agenda (60\u201390 mins)</a></li>\\n      <li><a href=\\"#decisions\\">The 3 decisions you must get</a></li>\\n      <li><a href=\\"#questions\\">Questions to ask (by role)</a></li>\\n      <li><a href=\\"#outputs\\">Outputs you produce after</a></li>\\n      <li><a href=\\"#anti\\">Common failure modes</a></li>\\n    </ul>\\n\\n    <h2 id=\\"why\\">1) Why this kickoff meeting exists</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        In enterprise delivery, pilots fail when you start building before the organisation commits to:\\n        <strong>who</strong> is in the pilot, <strong>what data</strong> is approved, and <strong>how success</strong> will be measured.\\n      </p>\\n      <div class=\\"ok\\">\\n        <strong>Kickoff objective:</strong> leave the meeting with hard decisions so engineering does not stall on approvals later.\\n      </div>\\n\\n      <h3 id=\\"in-plain-english\\">In plain English</h3>\\n      <ul>\\n        <li>The business wants a tool.</li>\\n        <li>You (AI lead) want to build it safely.</li>\\n        <li>Security/privacy/data owners want control.</li>\\n        <li>This meeting aligns everyone and locks the minimum safe pilot.</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"inputs\\">2) Inputs you bring (so the meeting is productive)</h2>\\n    <div class=\\"grid2\\">\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Document 1</div>\\n        <p><strong>AI Lead Response Doc</strong></p>\\n        <p class=\\"small\\">Scope, safety, architecture sketch, evaluation plan, asks.</p>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Document 2</div>\\n        <p><strong>Business Intake Brief</strong></p>\\n        <p class=\\"small\\">Problem statement, users, desired outcomes, constraints.</p>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Pre-work</div>\\n        <p><strong>Candidate pilot corpus list</strong></p>\\n        <p class=\\"small\\">Example: \u201cExec Forum minutes folder + packs folder (last 6 months)\u201d.</p>\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Pre-work</div>\\n        <p><strong>Draft success metrics</strong></p>\\n        <p class=\\"small\\">Time saved baseline plan + citation correctness measurement plan.</p>\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout\\">\\n      <strong>AI lead tip:</strong> Put the \u201cdecisions required\u201d at the top of the invite so people understand it is not a status meeting.\\n    </div>\\n\\n    <h2 id=\\"who\\">3) Who must attend (and why)</h2>\\n    <div class=\\"card\\">\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Role</th>\\n            <th>Why they must be there</th>\\n            <th>What decision they influence</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>Business Owner</strong></td>\\n            <td>Accountable for outcome + adoption.</td>\\n            <td>Pilot cohort, success metrics, rollout approach.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Sponsor / GM</strong></td>\\n            <td>Authority + unblocker (budget, access, priority).</td>\\n            <td>Go/no-go, escalation path, cross-team alignment.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>EA representative</strong></td>\\n            <td>Defines exec workflow and what \u201cusable output\u201d looks like.</td>\\n            <td>Output format, top questions, acceptance criteria.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Ops representative</strong></td>\\n            <td>Defines reliability needs and failure tolerance.</td>\\n            <td>Safe failure behavior, latency expectations, incident concerns.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Data Owner(s)</strong></td>\\n            <td>Approves corpus access and exclusions.</td>\\n            <td>What documents are allowed in pilot and how they\u2019re classified.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Security / IAM</strong></td>\\n            <td>Confirms approved patterns (identity, access control, secrets, logging).</td>\\n            <td>Access model constraints, audit requirements, network controls.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Privacy / Risk</strong></td>\\n            <td>Ensures the pilot meets obligations for sensitive data.</td>\\n            <td>Redaction/retention rules, allowed processing boundary.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>EM (Engineering Manager)</strong></td>\\n            <td>Confirms team capacity and delivery plan.</td>\\n            <td>Resourcing, sprint cadence, definition of done.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Lead AI Engineer</strong></td>\\n            <td>Chair of the meeting. Converts decisions into build plan.</td>\\n            <td>Defines evaluation gates, architecture pack, and delivery approach.</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"warn\\">\\n        <strong>Common mistake:</strong> leaving out the data owner or EA rep.\\n        Result: you build something nobody can approve or nobody finds usable.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"agenda\\">4) Agenda (60\u201390 minutes)</h2>\\n    <div class=\\"card\\">\\n      <ol>\\n        <li><strong>Context recap (5 mins)</strong> \u2014 problem, pilot intent, why citations and access control are mandatory.</li>\\n        <li><strong>Workflow + output contract (15 mins)</strong> \u2014 EA validates \u201cwhat good looks like\u201d.</li>\\n        <li><strong>Pilot scope decisions (20 mins)</strong> \u2014 cohort, corpus, exclusions, timeline.</li>\\n        <li><strong>Security/privacy gates (15 mins)</strong> \u2014 confirm constraints and approval path.</li>\\n        <li><strong>Success metrics + evaluation gates (15 mins)</strong> \u2014 define baseline and go-live criteria.</li>\\n        <li><strong>Next steps &amp; owners (10 mins)</strong> \u2014 assign people to each dependency.</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Chairing tip:</strong> Treat this as a decision-making meeting, not brainstorming.\\n        If discussion loops, park it and force a decision on the minimum safe pilot.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"decisions\\">5) The 3 decisions you must get (non-negotiable)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"decision-1-pilot-cohort\\">Decision 1 \u2014 Pilot cohort</h3>\\n      <ul>\\n        <li>Exactly who gets access (names or an org group)</li>\\n        <li>Who is the pilot champion (often an EA manager)</li>\\n      </ul>\\n\\n      <h3 id=\\"decision-2-pilot-corpus-approved-document-sets\\">Decision 2 \u2014 Pilot corpus (approved document sets)</h3>\\n      <ul>\\n        <li>Exact doc locations/sources</li>\\n        <li>Explicit exclusions (HR/legal/customer PII-heavy docs)</li>\\n        <li>Named data owner approval path</li>\\n      </ul>\\n\\n      <h3 id=\\"decision-3-success-metrics-and-go-live-gate\\">Decision 3 \u2014 Success metrics and go-live gate</h3>\\n      <ul>\\n        <li>2\u20133 measurable metrics (time saved, citation correctness, adoption)</li>\\n        <li>Definition of \u201cready to launch pilot\u201d (minimum eval thresholds)</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>If you get only these three decisions, you can start delivery.</strong>\\n        Everything else can iterate, but these prevent rework and approval deadlocks.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"questions\\">6) Questions to ask (by role)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"questions-for-the-business-owner\\">Questions for the Business Owner</h3>\\n      <ul>\\n        <li>\u201cWhat is the one outcome we must prove in 6 weeks?\u201d</li>\\n        <li>\u201cWhich user cohort will actually use this weekly?\u201d</li>\\n        <li>\u201cWho owns change management and onboarding?\u201d</li>\\n      </ul>\\n\\n      <h3 id=\\"questions-for-the-sponsor-gm\\">Questions for the Sponsor / GM</h3>\\n      <ul>\\n        <li>\u201cIf access approvals stall, who can unblock within 48 hours?\u201d</li>\\n        <li>\u201cWhat is the acceptable pilot timeline and what tradeoffs are allowed?\u201d</li>\\n      </ul>\\n\\n      <h3 id=\\"questions-for-the-ea-representative\\">Questions for the EA representative</h3>\\n      <ul>\\n        <li>\u201cWhat are the top 20 recurring questions execs ask?\u201d</li>\\n        <li>\u201cWhat counts as proof: snippet + link, or snippet + timestamp, or both?\u201d</li>\\n        <li>\u201cIf the tool says \u2018not found\u2019, what should it suggest next?\u201d</li>\\n      </ul>\\n\\n      <h3 id=\\"questions-for-ops\\">Questions for Ops</h3>\\n      <ul>\\n        <li>\u201cWhat happens if the answer is wrong?\u201d</li>\\n        <li>\u201cWhat latency is acceptable in urgent moments?\u201d</li>\\n        <li>\u201cWhat must the tool do when evidence is insufficient?\u201d</li>\\n      </ul>\\n\\n      <h3 id=\\"questions-for-data-owners\\">Questions for Data Owners</h3>\\n      <ul>\\n        <li>\u201cWhich folders/sites are approved, and which are explicitly excluded?\u201d</li>\\n        <li>\u201cAre there retention rules or classification tags we must enforce?\u201d</li>\\n      </ul>\\n\\n      <h3 id=\\"questions-for-security-iam-privacy-risk\\">Questions for Security/IAM + Privacy/Risk</h3>\\n      <ul>\\n        <li>\u201cWhat is the approved pattern for identity, service accounts, and audit logging?\u201d</li>\\n        <li>\u201cWhat data can be sent to the LLM and what must be redacted/blocked?\u201d</li>\\n        <li>\u201cWhat is the minimum go-live checklist for a pilot?\u201d</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"outputs\\">7) Outputs you produce after the meeting (within 24\u201348 hours)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"output-a-decision-record-1-page\\">Output A \u2014 Decision record (1 page)</h3>\\n      <ul>\\n        <li>Pilot cohort (names/group)</li>\\n        <li>Pilot corpus + exclusions</li>\\n        <li>Success metrics + go-live gate</li>\\n        <li>Owners for approvals and dependencies</li>\\n      </ul>\\n\\n      <h3 id=\\"output-b-architecture-review-pack-hld\\">Output B \u2014 Architecture review pack (HLD)</h3>\\n      <ul>\\n        <li>System diagram + trust boundaries</li>\\n        <li>Identity/access model</li>\\n        <li>Data flow (what is stored, what is sent to the LLM)</li>\\n        <li>Audit + logging plan</li>\\n        <li>Risks + mitigations</li>\\n      </ul>\\n\\n      <h3 id=\\"output-c-sprint-ready-backlog\\">Output C \u2014 Sprint-ready backlog</h3>\\n      <ul>\\n        <li>Epics by lane (ingestion, backend/security, retrieval/LLM/eval)</li>\\n        <li>Owners + milestones (vertical slice early)</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>AI lead tip:</strong> If you don\u2019t write a decision record, the organisation will \u201cremember\u201d the meeting differently.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"anti\\">8) Common failure modes (and how to avoid them)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>Failure:</strong> \u201cWe\u2019ll decide the corpus later.\u201d \u2192 <strong>Fix:</strong> no corpus, no pilot. Decide now.</li>\\n        <li><strong>Failure:</strong> \u201cIt should search everything.\u201d \u2192 <strong>Fix:</strong> pilot needs boundaries; scale comes later.</li>\\n        <li><strong>Failure:</strong> \u201cWe want it to be smart, no need for citations.\u201d \u2192 <strong>Fix:</strong> enterprise trust requires citations.</li>\\n        <li><strong>Failure:</strong> No EA/ops voice in the room \u2192 <strong>Fix:</strong> co-design is mandatory.</li>\\n        <li><strong>Failure:</strong> No owner for approvals \u2192 <strong>Fix:</strong> assign a person per dependency.</li>\\n      </ul>\\n\\n      <div class=\\"warn\\">\\n        <strong>What kills pilots fastest:</strong> unclear data ownership + unclear access control + unclear success metrics.\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Reusable artifacts</strong>\\n      Complete this stage with a filled-out <strong>Kickoff Meeting Agenda\\n      Email</strong> and <strong>Decision Record</strong>. Use the concrete\\n      scenario \u201cChandima mentioned no meeting on 1 Dec\u201d so assumptions,\\n      corpus boundaries, and expected citations are testable rather than\\n      abstract.\\n    </div>\\n  </div>"}'),l={title:"Pilot Kickoff Meeting (AI Lead): Why, What, Who \u2014 Enterprise Doc Q&A Example",slug:"/part1-enterprise-ai-delivery/04-kickoff-meeting",description:"This tutorial explains the kickoff meeting that happens right after the AI Lead submits the \u201cAI Lead Response Doc\u201d. The example is your Executive Document Q&A tool (meeting notes/packs \u2192 cited answers). The purpose of...",sidebar_label:"4. Pilot kickoff meeting",pagination_label:"4. Pilot kickoff meeting",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},u=[];function p(e){return(0,s.jsx)(a.A,{content:r})}function h(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(p,{...e})}):p()}}}]);